ON DUPLICATE KEY UPDATE name=VALUES(name),core_appearance=VALUES(core_appearance),safety_class=VALUES(safety_class),notes_text=VALUES(notes_text),source_url=VALUES(source_url);

ON DUPLICATE KEY UPDATE site_name=VALUES(site_name),common_features=VALUES(common_features),preferred_measurements=VALUES(preferred_measurements),clinical_note=VALUES(clinical_note),source_url=VALUES(source_url);

ON DUPLICATE KEY UPDATE term=VALUES(term),definition_text=VALUES(definition_text),notes_text=VALUES(notes_text);

ON DUPLICATE KEY UPDATE feature_name=VALUES(feature_name),description_text=VALUES(description_text),diagnostic_note=VALUES(diagnostic_note),source_url=VALUES(source_url);
